@app.api_route("/app/source-labels/thoracic/{asset:path}", methods=["GET", "HEAD"], include_in_schema=False)
async def thoracic_source_label_delivery(asset: str, request: Request):
    from .thoracic_source_labels import PREFIX, registry, references, validate_file
    src = PREFIX + asset
    if not src.isascii() or request.scope.get('raw_path', b'') != src.encode('ascii') or asset not in registry()['files']:
        return JSONResponse({'detail': 'Unknown source-label asset'}, status_code=404, headers={'Cache-Control': 'private, no-store'})
    references()
    validate_file(asset)
    response = await app.state.source_static.get_response('source-labels/thoracic/' + asset, request.scope)
    response.headers['Cache-Control'] = 'private, no-store'
    if asset == 'index.html':
        response.headers['Content-Security-Policy'] = CSP.replace("frame-ancestors 'none';", "frame-ancestors 'self';").replace("img-src 'self' data: ", "img-src 'self' data: blob: ")
    return response

if (asset.source_label_locator) {
  const locator = asset.source_label_locator;
  figure.dataset.sourceLabelFigure = locator.figure_id;
  const details = createElement('details', { class: 'rad-source-label-locator' },
    createElement('summary', {}, 'Inspect original image labels and marked observations'),
    createElement('p', {}, 'Publisher annotation locations and native pixel insets. Boxes are not tissue boundaries; signal panels do not identify valve leaflet morphology.'));
  let loaded = false;
  details.addEventListener('toggle', () => {
    if (!details.open || loaded) return;
    loaded = true;
    details.append(createElement('iframe', { src: locator.src, title: 'Original image label correspondence',
      loading: 'lazy', style: 'width:100%;height:760px;border:1px solid currentColor;display:block' }));
  });
  figure.append(details);
}
